package dev.rkotlin.hello

import android.app.Activity
import android.os.Bundle
import android.view.Gravity
import android.widget.LinearLayout
import android.widget.TextView
import com.airbnb.lottie.LottieAnimationView
import com.airbnb.lottie.LottieDrawable

class MainActivity : Activity() {
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        val dp = resources.displayMetrics.density

        // Kodi, the rkotlin mascot (app/src/main/assets/mascot.json, generated by assets/mascot in the repo)
        val mascot = LottieAnimationView(this).apply {
            setAnimation("mascot.json")
            repeatCount = LottieDrawable.INFINITE
            playAnimation()
        }
        val caption = TextView(this).apply {
            text = Greeter.greet("Android")
            textSize = 20f
            gravity = Gravity.CENTER
            setTextColor(0xFFF4EEFF.toInt())
            setPadding((24 * dp).toInt(), (8 * dp).toInt(), (24 * dp).toInt(), 0)
        }
        setContentView(LinearLayout(this).apply {
            orientation = LinearLayout.VERTICAL
            gravity = Gravity.CENTER
            setBackgroundColor(0xFF140F2B.toInt())
            addView(mascot, LinearLayout.LayoutParams((320 * dp).toInt(), (320 * dp).toInt()))
            addView(caption)
        })
    }
}
